class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - ord('a')] += 1
        for _ in range(t):
            new = [0] * 26
            z = cnt[25]
            new[0] = z
            new[1] = (cnt[0] + z) % MOD
            for i in range(1, 25):
                new[i + 1] = cnt[i]
            cnt = [x % MOD for x in new]
        return sum(cnt) % MOD
