import json
from hypothesis import strategies as st

MOD = 10**9 + 7


@st.composite
def gen(draw):
    length = draw(st.integers(1, 6))
    alphabet = st.sampled_from(list("abcxyz") + ["z", "z", "a"])
    chars = draw(st.lists(alphabet, min_size=length, max_size=length))
    s = "".join(chars)
    t = draw(st.integers(1, 12))
    return f"{json.dumps(s)}\n{json.dumps(t)}\n"


def validate(inp):
    lines = inp.strip().split("\n")
    if len(lines) != 2:
        return False
    try:
        s = json.loads(lines[0])
        t = json.loads(lines[1])
    except Exception:
        return False
    if not isinstance(s, str) or not isinstance(t, int) or isinstance(t, bool):
        return False
    if not (1 <= len(s) <= 10**5):
        return False
    if not all('a' <= c <= 'z' for c in s):
        return False
    if not (1 <= t <= 10**5):
        return False
    return True


def ref(inp):
    lines = inp.strip().split("\n")
    s = json.loads(lines[0])
    t = json.loads(lines[1])
    cur = s
    for _ in range(t):
        nxt = []
        for c in cur:
            if c == 'z':
                nxt.append("ab")
            else:
                nxt.append(chr(ord(c) + 1))
        cur = "".join(nxt)
    return json.dumps(len(cur) % MOD)
